INSERT INTO repo_cf_values (cf_value_id, education_level, sub_heading, text, status) VALUES ('CFV_SDG05_TVET_009', 'TVET', 'Leadership, empowerment and accountability', 'Take personal responsibility for addressing gender-based discrimination and supporting those affected.', 'Active'), ('CFV_SDG05_TVET_010', 'TVET', 'Leadership, empowerment and accountability', 'Promote emotional literacy and supportive environments that allow all individuals to express themselves without fear of judgment.', 'Active'), ('CFV_SDG05_TVET_011', 'TVET', 'Awareness, advocacy and global citizenship', 'Stay informed about gender equality trends, laws and best practices in the workplace and education.', 'Active'), ('CFV_SDG05_TVET_012', 'TVET', 'Awareness, advocacy and global citizenship', 'Engage in dialogue and action that promote awareness of SDG5 and the importance of gender equality for sustainable development.', 'Active'), ('CFV_SDG05_TVET_013', 'TVET', 'Awareness, advocacy and global citizenship', 'Promote the value of diverse teams and inclusive workplaces as a foundation for innovation and growth.', 'Active'), ('CFV_SDG05_TVET_014', 'TVET', 'Awareness, advocacy and global citizenship', 'Be an active agent of change, advocating for gender equality policies in your institution, community or industry.', 'Active'), ('CFV_SDG05_TVET_015', 'TVET', 'Awareness, advocacy and global citizenship', 'Communicate the role of gender equality in achieving broader societal goals and speak out against inequality and discrimination.', 'Active'), ('CFV_SDG05_TVET_016', 'TVET', 'Systemic change and sustainability', 'Champion reforms that remove systemic obstacles to gender equality in education and the labour market.', 'Active'), ('CFV_SDG05_TVET_017', 'TVET', 'Systemic change and sustainability', 'Collaborate with others to create scalable, sustainable solutions to gender inequality in technical and vocational sectors.', 'Active'), ('CFV_SDG05_TVET_018', 'TVET', 'Systemic change and sustainability', 'Recognise that gender equality is an evolving goal requiring continuous learning, reflection and adaptation.', 'Active'), ('CFV_SDG05_TVET_019', 'TVET', 'Systemic change and sustainability', 'Navigate diversity effectively within potentially hostile environments.', 'Active'), ('CFV_SDG05_TVET_020', 'TVET', 'Systemic change and sustainability', 'Commit to equipping educators and learners with context-specific strategies to counter discrimination, harassment and gender-based hostility in professional and civic spaces.', 'Active'), ('CFV_SDG05_TVET_021', 'TVET', 'Systemic change and sustainability', 'Develop and apply approaches that address harmful masculinities and promote respectful, inclusive forms of identity and leadership.', 'Active'), ('CFV_SDG05_TVET_022', 'TVET', 'Systemic change and sustainability', 'Collaborate with various stakeholders, including educators, policymakers, employers and advocacy groups, to strengthen gender-responsive practices and ensure that gender equality is a core component of TVET systems.', 'Active'), ('CFV_SDG05_TER_001', 'Tertiary education', 'Equity, justice and empathy', 'Value gender equality as central to human rights, democracy and inclusive development.', 'Active'), ('CFV_SDG05_TER_002', 'Tertiary education', 'Equity, justice and empathy', 'Show empathy and allyship by recognising the lived experiences of those affected by gender-based exclusion and violence.', 'Active'), ('CFV_SDG05_TER_003', 'Tertiary education', 'Equity, justice and empathy', 'Commit to challenging patriarchal norms, sexism and discrimination in both academic and community settings.', 'Active'), ('CFV_SDG05_TER_004', 'Tertiary education', 'Leadership and responsibility', 'Take personal and professional responsibility for promoting inclusive, respectful learning and working environments.', 'Active'), ('CFV_SDG05_TER_005', 'Tertiary education', 'Leadership and responsibility', 'Demonstrate ethical leadership by advocating for gender-equitable policies, curricula and institutional reforms.', 'Active'), ('CFV_SDG05_TER_006', 'Tertiary education', 'Leadership and responsibility', 'Encourage accountability within institutions for achieving gender equality commitments.', 'Active'), ('CFV_SDG05_TER_007', 'Tertiary education', 'Intersectionality and inclusiveness', 'Recognise and respond to the unique challenges faced by women and gender minorities at the intersection of race, class, disability and sexual orientation.', 'Active'), ('CFV_SDG05_TER_008', 'Tertiary education', 'Intersectionality and inclusiveness', 'Value diversity and promote inclusive practices that respect the rights and dignity of all learners.', 'Active'), ('CFV_SDG05_TER_009', 'Tertiary education', 'Global frameworks and standards', 'Evaluate and apply international gender standards and frameworks (for example, CEDAW, SDG5) to local contexts, ensuring that educational policies are aligned with global commitments to gender equality.', 'Active'), ('CFV_SDG05_TER_010', 'Tertiary education', 'Global frameworks and standards', 'Analyse and apply solutions to overcome barriers to gender equality, including policy changes, community initiatives and international frameworks.', 'Active'), ('CFV_SDG05_TER_011', 'Tertiary education', 'Global frameworks and standards', 'Recognise the importance of creating and implementing strategies that encourage gender equality through education, lifelong learning and leadership.', 'Active'), ('CFV_SDG05_TER_012', 'Tertiary education', 'Global frameworks and standards', 'Emphasise the role of individuals in contributing to a more equitable and inclusive society through advocacy, education and direct action.', 'Active'), ('CFV_SDG05_TER_013', 'Tertiary education', 'Advocacy and global citizenship', 'Engage in advocacy, research and policy reform initiatives that contribute to SDG5.', 'Active'), ('CFV_SDG05_TER_014', 'Tertiary education', 'Advocacy and global citizenship', 'Advocate for and design programmes and policies that support marginalised girls and women, ensuring they have access to education and opportunities.', 'Active'), ('CFV_SDG05_TER_015', 'Tertiary education', 'Advocacy and global citizenship', 'Commit to developing gender-sensitive, culturally relevant pedagogy that meets the diverse needs of female learners, providing mentorship, role models and safe spaces for girls.', 'Active'), ('CFV_SDG05_TER_016', 'Tertiary education', 'Advocacy and global citizenship', 'Support the participation of men and boys in gender equality efforts, promoting shared responsibility and transformative masculinities.', 'Active'), ('CFV_SDG05_TER_017', 'Tertiary education', 'Advocacy and global citizenship', 'Encourage men and boys to engage in discussions about the impact of patriarchal social relations and their role in challenging gender-based inequalities.', 'Active'), ('CFV_SDG05_TER_018', 'Tertiary education', 'Advocacy and global citizenship', 'Promote an understanding of intersectionality, recognising how gender inequality interacts with other forms of discrimination such as race, class, disability and individual identity.', 'Active'), ('CFV_SDG05_TER_019', 'Tertiary education', 'Advocacy and global citizenship', 'Internalise the idea that education can break cycles of poverty, violence and discrimination.', 'Active'), ('CFV_SDG05_TER_020', 'Tertiary education', 'Advocacy and global citizenship', 'Cultivate the attitude that gender equality is not just a women’s issue but a shared societal responsibility. Encourage students to believe in the importance of involving men and boys in the fight for gender equality.', 'Active'), ('CFV_SDG05_TER_021', 'Tertiary education', 'Advocacy and global citizenship', 'Promote inclusive communication that challenges stereotypes and uplifts marginalised voices.', 'Active'), ('CFV_SDG05_TER_022', 'Tertiary education', 'Advocacy and global citizenship', 'Stay informed and responsive to global gender equality trends, data and frameworks.', 'Active'), ('CFV_SDG05_TER_023', 'Tertiary education', 'Transformative change and accountability', 'Believe in education as a transformative tool to dismantle cycles of discrimination and empower all genders.', 'Active'), ('CFV_SDG05_TER_024', 'Tertiary education', 'Transformative change and accountability', 'Embrace lifelong learning and reflection to evolve strategies that advance gender equality.', 'Active'), ('CFV_SDG05_TER_025', 'Tertiary education', 'Transformative change and accountability', 'Cultivate a personal commitment to building just, inclusive and equitable academic and professional spaces.', 'Active'), ('CFV_SDG05_ADULT_001', 'Adult education', 'Equity, justice and empathy', 'Value gender equality as central to human rights, democracy and inclusive development.', 'Active'), ('CFV_SDG05_ADULT_002', 'Adult education', 'Equity, justice and empathy', 'Show empathy and allyship by recognising the lived experiences of those affected by gender-based exclusion and violence.', 'Active'), ('CFV_SDG05_ADULT_003', 'Adult education', 'Equity, justice and empathy', 'Commit to challenging patriarchal norms, sexism and discrimination in both academic and community settings.', 'Active'), ('CFV_SDG05_ADULT_004', 'Adult education', 'Leadership and responsibility', 'Take personal and professional responsibility for promoting inclusive, respectful learning and working environments.', 'Active'), ('CFV_SDG05_ADULT_005', 'Adult education', 'Leadership and responsibility', 'Demonstrate ethical leadership by advocating for gender-equitable policies, curricula and institutional reforms.', 'Active'), ('CFV_SDG05_ADULT_006', 'Adult education', 'Leadership and responsibility', 'Monitor accountability within institutions for achieving gender equality commitments.', 'Active'), ('CFV_SDG05_ADULT_007', 'Adult education', 'Intersectionality and inclusiveness', 'Recognise and respond to the unique challenges faced by women and gender minorities at the intersection of race, class, disability and sexual orientation.', 'Active'), ('CFV_SDG05_ADULT_008', 'Adult education', 'Intersectionality and inclusiveness', 'Value diversity and promote inclusive practices that respect the rights and dignity of all learners.', 'Active'), ('CFV_SDG05_ADULT_009', 'Adult education', 'Intersectionality and inclusiveness', 'Promote education and leadership pathways that reflect intersectional and community-based perspectives.', 'Active'), ('CFV_SDG05_ADULT_010', 'Adult education', 'Advocacy and global citizenship', 'Engage in advocacy, research and policy reform initiatives that contribute to SDG5.', 'Active'), ('CFV_SDG05_ADULT_011', 'Adult education', 'Advocacy and global citizenship', 'Support the participation of men and boys in gender equality efforts, promoting shared responsibility and transformative masculinities.', 'Active') ON CONFLICT DO NOTHING;